import{_ as t,c as i,o as a,ae as n}from"./chunks/framework.DMK_uHmU.js";const g=JSON.parse('{"title":"LaunchPad User Guide","description":"","frontmatter":{},"headers":[],"relativePath":"Administration/AI-Management/Settings/launchpad.md","filePath":"Administration/AI-Management/Settings/launchpad.md"}'),o={name:"Administration/AI-Management/Settings/launchpad.md"};function l(s,e,r,c,d,h){return a(),i("div",null,e[0]||(e[0]=[n('<h1 id="launchpad-user-guide" tabindex="-1">LaunchPad User Guide <a class="header-anchor" href="#launchpad-user-guide" aria-label="Permalink to &quot;LaunchPad User Guide&quot;">​</a></h1><h2 id="table-of-contents" tabindex="-1">Table of Contents <a class="header-anchor" href="#table-of-contents" aria-label="Permalink to &quot;Table of Contents&quot;">​</a></h2><ul><li><a href="#launchpad-user-guide">LaunchPad User Guide</a><ul><li><a href="#table-of-contents">Table of Contents</a></li><li><a href="#introduction">Introduction</a></li><li><a href="#getting-started">Getting Started</a></li><li><a href="#launchpad-interface-overview">LaunchPad Interface Overview</a></li><li><a href="#managing-sections">Managing Sections</a><ul><li><a href="#section-types">Section Types</a></li><li><a href="#adding-sections">Adding Sections</a></li><li><a href="#configuring-sections">Configuring Sections</a></li><li><a href="#reordering-sections">Reordering Sections</a></li></ul></li><li><a href="#content-cards">Content Cards</a></li><li><a href="#search-functionality">Search Functionality</a></li><li><a href="#customization-options">Customization Options</a><ul><li><a href="#section-visibility">Section Visibility</a></li><li><a href="#card-appearance">Card Appearance</a></li></ul></li><li><a href="#troubleshooting">Troubleshooting</a></li></ul></li></ul><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>LaunchPad is a customizable home screen for the AI Assistant that provides quick access to your most frequently used content. This guide will walk you through all the features and functionality to help you create an optimal end-user experience.</p><h2 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h2><p>When you first access the LaunchPad, you&#39;ll see a greeting with your name and the question &quot;What would you like to do today?&quot; along with any configured content sections.</p><p>The LaunchPad allows you to:</p><ul><li>Create and customize multiple content sections</li><li>Filter content by type, topic, or tags</li><li>Search across all available content</li><li>Reorder sections to prioritize important information</li><li>Enable or disable individual sections</li></ul><h2 id="launchpad-interface-overview" tabindex="-1">LaunchPad Interface Overview <a class="header-anchor" href="#launchpad-interface-overview" aria-label="Permalink to &quot;LaunchPad Interface Overview&quot;">​</a></h2><p>The LaunchPad consists of several key components:</p><ol><li><strong>Header Area</strong>: Contains your personalized greeting and global search bar</li><li><strong>Toggle Control</strong>: Enables or disables the entire LaunchPad functionality</li><li><strong>Section Rows</strong>: Customizable content containers that display filtered content</li><li><strong>Content Cards</strong>: Individual items that appear in each section</li><li><strong>Admin Controls</strong>: Section configuration and ordering tools (visible to users with appropriate permissions)</li></ol><h2 id="managing-sections" tabindex="-1">Managing Sections <a class="header-anchor" href="#managing-sections" aria-label="Permalink to &quot;Managing Sections&quot;">​</a></h2><h3 id="section-types" tabindex="-1">Section Types <a class="header-anchor" href="#section-types" aria-label="Permalink to &quot;Section Types&quot;">​</a></h3><p>LaunchPad supports three types of sections:</p><ol><li><strong>Featured</strong> (Protected): Displays content marked as &quot;featured&quot; with images and descriptions</li><li><strong>DynamicTopic</strong> (Protected): Automatically categorizes content based on its assigned topics</li><li><strong>Topic</strong>: User-defined sections with custom filtering options</li></ol><h3 id="adding-sections" tabindex="-1">Adding Sections <a class="header-anchor" href="#adding-sections" aria-label="Permalink to &quot;Adding Sections&quot;">​</a></h3><p>To add a new section:</p><ol><li>Click the &quot;Add Section&quot; button located at the bottom right of the screen</li><li>Configure the section settings in the dialog that appears</li><li>Click &quot;Done&quot; to save your changes</li></ol><h3 id="configuring-sections" tabindex="-1">Configuring Sections <a class="header-anchor" href="#configuring-sections" aria-label="Permalink to &quot;Configuring Sections&quot;">​</a></h3><p>Each section can be customized with the following settings:</p><ol><li><strong>Section Name</strong>: The title displayed above the section</li><li><strong>Match By Content Type</strong>: Filter content by type (Blueprint, Document, Link, Knowledgebase)</li><li><strong>Match By Topic</strong>: Filter content to display only items with a specific topic</li><li><strong>Match By Tags</strong>: Filter content to display only items with specific tags</li><li><strong>Section Appearance</strong>: Customize background and text colors for both light and dark modes</li></ol><p>To configure an existing section:</p><ol><li>Find the gear icon next to the section title</li><li>Click the icon to open the configuration dialog</li><li>Adjust settings as needed</li><li>Click &quot;Done&quot; to save changes</li></ol><p>For DynamicTopic sections, you can also choose between &quot;By Row&quot; or &quot;By Column&quot; display formats.</p><h3 id="reordering-sections" tabindex="-1">Reordering Sections <a class="header-anchor" href="#reordering-sections" aria-label="Permalink to &quot;Reordering Sections&quot;">​</a></h3><p>To change the order of sections:</p><ol><li>Click the &quot;Section Order&quot; button in the top menu bar</li><li>In the dialog that appears, drag and drop sections using the handle (⋮⋮) on the left</li><li>The order of sections will update automatically</li><li>Close the dialog when finished</li></ol><h2 id="content-cards" tabindex="-1">Content Cards <a class="header-anchor" href="#content-cards" aria-label="Permalink to &quot;Content Cards&quot;">​</a></h2><p>Content cards in LaunchPad display different types of content:</p><ol><li><p><strong>Blueprint Cards</strong>: Display blueprint names or conversation starters</p><ul><li>Regular blueprints appear as standard cards</li><li>Blueprints with conversation starters show each starter as a separate card</li></ul></li><li><p><strong>Document Cards</strong>: Show document titles in cards with customizable background and text colors</p></li><li><p><strong>Web Link Cards</strong>: Display an icon and link title in a specialized format with:</p><ul><li>Custom icon</li><li>Icon background and border colors</li><li>Link name displayed below the icon</li></ul></li></ol><p>Cards appear in a horizontal scrolling row within their assigned section. Users can click on a card to access the associated content.</p><h2 id="search-functionality" tabindex="-1">Search Functionality <a class="header-anchor" href="#search-functionality" aria-label="Permalink to &quot;Search Functionality&quot;">​</a></h2><p>The global search bar allows users to filter all content across all sections:</p><ol><li>Enter search text in the search field at the top right</li><li>Results will filter in real-time as you type</li><li>Content matching the search term (by name or tag) will be displayed</li><li>Empty sections are automatically hidden</li></ol><h2 id="customization-options" tabindex="-1">Customization Options <a class="header-anchor" href="#customization-options" aria-label="Permalink to &quot;Customization Options&quot;">​</a></h2><h3 id="section-visibility" tabindex="-1">Section Visibility <a class="header-anchor" href="#section-visibility" aria-label="Permalink to &quot;Section Visibility&quot;">​</a></h3><p>Each section can be individually enabled or disabled:</p><ol><li>Use the toggle switch next to the section title</li><li>Disabled sections will display a message indicating they are currently disabled</li></ol><h3 id="card-appearance" tabindex="-1">Card Appearance <a class="header-anchor" href="#card-appearance" aria-label="Permalink to &quot;Card Appearance&quot;">​</a></h3><p>Section cards can be customized with different colors:</p><ol><li>Background color (light mode)</li><li>Text color (light mode)</li><li>Background color (dark mode)</li><li>Text color (dark mode)</li></ol><p>Preview your customizations in real-time within the section configuration dialog using the light/dark mode toggle.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p><strong>Issue</strong>: Content not appearing in a section</p><ul><li>Verify the content matches the section&#39;s filtering criteria (content type, topic, tags)</li><li>Ensure the content&#39;s publish dates are valid</li><li>Check that the section is enabled</li></ul><p><strong>Issue</strong>: Unable to delete a section</p><ul><li>Featured and DynamicTopic sections are protected and cannot be deleted</li><li>These sections can be disabled instead</li></ul><p><strong>Issue</strong>: Section appears empty</p><ul><li>If no content matches the section&#39;s filtering criteria, the section will be hidden</li><li>Adjust the filtering criteria or add matching content</li></ul><p><strong>Issue</strong>: Changes not saving</p><ul><li>Ensure you have appropriate permissions (Admin, Content, or Manager roles)</li><li>Click &quot;Done&quot; after making changes to save them</li></ul><hr><p>For additional assistance, contact your system administrator or refer to the advanced configuration documentation.</p>',54)]))}const p=t(o,[["render",l]]);export{g as __pageData,p as default};
